  ('wizard', 'Wizard', '{"team":"minion","script":"experimental","wake":"both","nightOrder":20,"tags":["ability-granting"],"reminders":2,"jinxes":0}'::jsonb, '{"inBase3":false,"isExperimental":true,"isTraveller":false,"isStoryteller":false}'::jsonb),
  ('wraith', 'Wraith', '{"team":"minion","script":"experimental","wake":"both","nightOrder":3,"tags":["information","self-targeting"],"reminders":0,"jinxes":3}'::jsonb, '{"inBase3":false,"isExperimental":true,"isTraveller":false,"isStoryteller":false}'::jsonb),
  ('xaan', 'Xaan', '{"team":"minion","script":"experimental","wake":"both","nightOrder":15,"tags":["misinformation","setup-modifier"],"reminders":4,"jinxes":0}'::jsonb, '{"inBase3":false,"isExperimental":true,"isTraveller":false,"isStoryteller":false}'::jsonb),
  ('yaggababble', 'Yaggababble', '{"team":"demon","script":"experimental","wake":"both","nightOrder":55,"tags":["information"],"reminders":3,"jinxes":1}'::jsonb, '{"inBase3":false,"isExperimental":true,"isTraveller":false,"isStoryteller":false}'::jsonb),
  ('zealot', 'Zealot', '{"team":"outsider","script":"experimental","wake":"never","nightOrder":null,"tags":["voting-social"],"reminders":0,"jinxes":3}'::jsonb, '{"inBase3":false,"isExperimental":true,"isTraveller":false,"isStoryteller":false}'::jsonb),
  ('zenomancer', 'Zenomancer', '{"team":"loric","script":"loric","wake":"never","nightOrder":null,"tags":["rules-modifier"],"reminders":3,"jinxes":0}'::jsonb, '{"inBase3":false,"isExperimental":false,"isTraveller":false,"isStoryteller":true}'::jsonb),
  ('zombuul', 'Zombuul', '{"team":"demon","script":"bmr","wake":"other","nightOrder":41,"tags":["killing","misinformation"],"reminders":2,"jinxes":1}'::jsonb, '{"inBase3":true,"isExperimental":false,"isTraveller":false,"isStoryteller":false}'::jsonb)
on conflict (id) do update set
  name  = excluded.name,
  attrs = excluded.attrs,
  pools = excluded.pools;

-- norm_name is added by 05_pvp.sql, so only touch it once that has run.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'characters'
      and column_name = 'norm_name'
  ) then
    update public.characters
    set norm_name = lower(regexp_replace(name, '[^A-Za-z0-9]', '', 'g'));
  end if;
end
$$;

-- Drop anything no longer in the official data, but only where nothing
-- references it. A character that has been played stays, and is reported
-- rather than silently kept or forcibly removed.
do $$
declare
  keep text[] := array[
    'acrobat',
    'alhadikhia',
    'alchemist',
    'alsaahir',
    'amnesiac',
    'angel',
    'apprentice',
