    'eviltwin',
    'exorcist',
    'fanggu',
    'farmer',
    'fearmonger',
    'ferryman',
    'fibbin',
    'fiddler',
    'fisherman',
    'flowergirl',
    'fool',
    'fortuneteller',
    'gambler',
    'gangster',
    'gardener',
    'general',
    'gnome',
    'goblin',
    'godofug',
    'godfather',
    'golem',
    'goon',
    'gossip',
    'grandmother',
    'gunslinger',
    'harlot',
    'harpy',
    'hatter',
    'hellslibrarian',
    'heretic',
    'hermit',
    'highpriestess',
    'hindu',
    'huntsman',
    'imp',
    'innkeeper',
    'investigator',
    'judge',
    'juggler',
    'kazali',
    'king',
    'klutz',
    'knaves',
    'knight',
    'legion',
    'leviathan',
    'librarian',
    'lilmonsta',
    'lleech',
    'lordoftyphon',
    'lunatic',
    'lycanthrope',
    'magician',
    'marionette',
    'mastermind',
    'mathematician',
    'matron',
    'mayor',
    'mezepheles',
    'minstrel',
    'monk',
    'moonchild',
    'mutant',
    'nightwatchman',
    'nodashii',
    'noble',
    'ogre',
    'ojo',
    'oracle',
    'organgrinder',
    'pacifist',
    'philosopher',
    'pithag',
    'pixie',
    'plaguedoctor',
    'po',
    'poisoner',
    'politician',
    'pope',
    'poppygrower',
    'preacher',
    'princess',
    'professor',
    'psychopath',
    'pukka',
    'puzzlemaster',
    'ravenkeeper',
    'recluse',
    'revolutionary',
    'riot',
    'sage',
    'sailor',
    'saint',
    'savant',
    'scapegoat',
    'scarletwoman',
    'seamstress',
    'sentinel',
    'shabaloth',
    'shugenja',
    'slayer',
    'snakecharmer',
    'snitch',
    'soldier',
    'spiritofivory',
    'spy',
    'steward',
    'stormcatcher',
    'summoner',
    'sweetheart',
    'tealady',
    'thief',
    'tinker',
    'tor',
    'towncrier',
    'toymaker',
    'undertaker',
    'ventriloquist',
    'vigormortis',
    'villageidiot',
    'virgin',
    'vizier',
    'vortox',
    'voudon',
    'washerwoman',
    'widow',
    'witch',
    'wizard',
    'wraith',
    'xaan',
    'yaggababble',
    'zealot',
    'zenomancer',
    'zombuul'
  ];
  stale text[];
  blocked text[];
  fk record;
  n int;
  id text;
begin
  select coalesce(array_agg(c.id), '{}') into stale
  from public.characters c where c.id <> all (keep);

  if array_length(stale, 1) is null then return; end if;

  blocked := '{}';
  foreach id in array stale loop
    -- Walk every foreign key that points at characters(id) rather than
    -- hard-coding the list, so a table added later is covered too.
    for fk in
      select tc.table_name, kcu.column_name
      from information_schema.table_constraints tc
      join information_schema.key_column_usage kcu
        on kcu.constraint_name = tc.constraint_name
      join information_schema.constraint_column_usage ccu
        on ccu.constraint_name = tc.constraint_name
      where tc.constraint_type = 'FOREIGN KEY'
        and ccu.table_name = 'characters' and ccu.column_name = 'id'
    loop
      execute format('select count(*) from public.%I where %I = $1', fk.table_name, fk.column_name)
        into n using id;
      if n > 0 then
        blocked := blocked || id;
        exit;
      end if;
    end loop;
  end loop;

  delete from public.characters c
  where c.id <> all (keep) and c.id <> all (blocked);

  if array_length(blocked, 1) > 0 then
    raise notice 'Kept % character(s) no longer in the official data because they are referenced by existing games: %', array_length(blocked, 1), blocked;
  end if;
end
$$;

commit;
